/*!50003 CREATE*/ /*!50017 DEFINER=CURRENT_USER*/ /*!50003 TRIGGER `trg_tbc_categories_after_update` AFTER UPDATE ON `tb_categories` FOR EACH ROW BEGIN
    DECLARE changes_detail TEXT DEFAULT '';

    IF NOT (OLD.name <=> NEW.name) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Nombre: "',
            OLD.name,
            '" -> "',
            NEW.name,
            '"; '
        );
    END IF;

    IF NOT (OLD.description <=> NEW.description) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Descripcion: "',
            COALESCE(OLD.description, 'NULL'),
            '" -> "',
            COALESCE(NEW.description, 'NULL'),
            '"; '
        );
    END IF;

    IF NOT (OLD.sup_id_category <=> NEW.sup_id_category) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Categoria superior: ',
            COALESCE(CAST(OLD.sup_id_category AS CHAR), 'NULL'),
            ' -> ',
            COALESCE(CAST(NEW.sup_id_category AS CHAR), 'NULL'),
            '; '
        );
    END IF;

    IF NOT (OLD.status <=> NEW.status) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Estado: ',
            CAST(OLD.status AS UNSIGNED),
            ' -> ',
            CAST(NEW.status AS UNSIGNED),
            '; '
        );
    END IF;

    IF changes_detail <> '' THEN
        INSERT INTO tb_logs (
            table_name,
            record_id,
            table_operation,
            db_user,
            table_description
        )
        VALUES (
            'tb_categories',
            NEW.ID,
            'Update',
            USER(),
            TRIM(changes_detail)
        );
    END IF;
END */;;
DELIMITER ;
