/*!50003 CREATE*/ /*!50017 DEFINER=CURRENT_USER*/ /*!50003 TRIGGER `trg_tbc_categories_after_delete` AFTER DELETE ON `tb_categories` FOR EACH ROW BEGIN
    INSERT INTO tb_logs
    (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description,
        operation_date,
        operation_status
    )
    VALUES
    (
        'tb_categories',
        OLD.ID,
        'Delete',
        USER(),
        CONCAT(
            'Categoria eliminada. ID=',
            OLD.ID,
            ', nombre=',
            OLD.name,
            ', descripcion=',
            COALESCE(OLD.description, 'NULL'),
            ', categoria_superior=',
            COALESCE(CAST(OLD.sup_id_category AS CHAR), 'NULL'),
            ', status=',
            COALESCE(CAST(OLD.status AS UNSIGNED), 0)
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
