/*!50003 CREATE*/ /*!50017 DEFINER=CURRENT_USER*/ /*!50003 TRIGGER `trg_tb_product_categories_after_update` AFTER UPDATE ON `tb_product_categories` FOR EACH ROW BEGIN
    DECLARE changes_detail TEXT DEFAULT '';

    IF NOT (OLD.product_Id <=> NEW.product_Id) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Producto: ',
            OLD.product_Id,
            ' -> ',
            NEW.product_Id,
            '; '
        );
    END IF;

    IF NOT (OLD.category_Id <=> NEW.category_Id) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Categoria: ',
            OLD.category_Id,
            ' -> ',
            NEW.category_Id,
            '; '
        );
    END IF;

    IF NOT (OLD.status <=> NEW.status) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Estado: ',
            CAST(OLD.status AS UNSIGNED),
            ' -> ',
            CAST(NEW.status AS UNSIGNED),
            '; '
        );
    END IF;

    IF changes_detail <> '' THEN
        INSERT INTO tb_logs (
            table_name,
            record_id,
            table_operation,
            db_user,
            table_description
        )
        VALUES (
            'tb_product_categories',
            NEW.product_Id,
            'Update',
            USER(),
            CONCAT('Vinculo producto ', OLD.product_Id, ' / categoria ', OLD.category_Id, '. ', TRIM(changes_detail))
        );
    END IF;
END */;;
DELIMITER ;
