/*!50003 CREATE*/ /*!50017 DEFINER=CURRENT_USER*/ /*!50003 TRIGGER `trg_tb_product_categories_after_delete` AFTER DELETE ON `tb_product_categories` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        record_id,
        table_operation,
        db_user,
        table_description,
        operation_date,
        operation_status
    )
    VALUES (
        'tb_product_categories',
        OLD.product_Id,
        'Delete',
        USER(),
        CONCAT(
            'Vinculo eliminado. Producto=',
            OLD.product_Id,
            ', categoria=',
            OLD.category_Id,
            ', status=',
            CAST(OLD.status AS UNSIGNED)
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
