/*!50003 CREATE*/ /*!50017 DEFINER=CURRENT_USER*/ /*!50003 TRIGGER `trg_tb_products_after_update` AFTER UPDATE ON `tb_products` FOR EACH ROW BEGIN
    DECLARE changes_detail TEXT DEFAULT '';

    IF NOT (OLD.SKU <=> NEW.SKU) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'SKU: "',
            OLD.SKU,
            '" -> "',
            NEW.SKU,
            '"; '
        );
    END IF;

    IF NOT (OLD.name <=> NEW.name) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Nombre: "',
            OLD.name,
            '" -> "',
            NEW.name,
            '"; '
        );
    END IF;

    IF NOT (OLD.description <=> NEW.description) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Descripcion: "',
            COALESCE(OLD.description, 'NULL'),
            '" -> "',
            COALESCE(NEW.description, 'NULL'),
            '"; '
        );
    END IF;

    IF NOT (OLD.current_price <=> NEW.current_price) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Precio: $',
            OLD.current_price,
            ' -> $',
            NEW.current_price,
            '; '
        );
    END IF;

    IF NOT (OLD.current_stock <=> NEW.current_stock) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Stock: ',
            OLD.current_stock,
            ' -> ',
            NEW.current_stock,
            '; '
        );
    END IF;

    IF NOT (OLD.status <=> NEW.status) THEN
        SET changes_detail = CONCAT(
            changes_detail,
            'Estado: ',
            COALESCE(CAST(OLD.status AS UNSIGNED), 0),
            ' -> ',
            COALESCE(CAST(NEW.status AS UNSIGNED), 0),
            '; '
        );
    END IF;

    IF changes_detail <> '' THEN
        INSERT INTO tb_logs (
            table_name,
            record_id,
            table_operation,
            db_user,
            table_description
        )
        VALUES (
            'tb_products',
            NEW.ID,
            'Update',
            USER(),
            TRIM(changes_detail)
        );
    END IF;
END */;;
DELIMITER ;
